INSERT INTO `npc_text` (`ID`, `text0_0`, `text0_1`, `BroadcastTextID0`, `lang0`, `Probability0`, `em0_0`, `em0_1`, `em0_2`, `em0_3`, `em0_4`, `em0_5`)
VALUES
(87571, '你好。$B$B我是加拉克·双棍。$B$B你说我只拿着一根棍子？哈，另一根我藏起来留到特殊场合用。$B$B感受背后的风吧，朋友，把武器握紧。你永远不知道什么时候会需要用到它们。$B$B说到这个，我可以教你怎么用。', '你好。$B$B我是加拉克·双棍。$B$B你说我只拿着一根棍子？哈，另一根我藏起来留到特殊场合用。$B$B感受背后的风吧，朋友，把武器握紧。你永远不知道什么时候会需要用到它们。$B$B说到这个，我可以教你怎么用。', 0, 0, 1, 1, 1, 0, 0, 0, 0),
(30501, '有些人认为牛头人不配成为唤星者。他们不明白，牛头人崇拜的是与暗夜精灵称为艾露恩相同存在，只是名字不同——穆莎，大地母亲之眼。', '有些人认为牛头人不配成为唤星者。他们不明白，牛头人崇拜的是与暗夜精灵称为艾露恩相同存在，只是名字不同——穆莎，大地母亲之眼。', 0, 0, 1, 1, 1, 0, 0, 0, 0),
(130501, '穆莎的光芒只照耀唤星者，$C。群星并未选择你走上这条道路。', '穆莎的光芒只照耀唤星者，$C。群星并未选择你走上这条道路。', 0, 0, 1, 0, 0, 0, 0, 0, 0),
(32037, '大地母亲指引着我，我并不只是被元素本身所束缚。解放你自己，让大地母亲带给你智慧。$B$B与大地融为一体，$C。让我来教你我的意思……', '大地母亲指引着我，我并不只是被元素本身所束缚。解放你自己，让大地母亲带给你智慧。$B$B与大地融为一体，$C。让我来教你我的意思……', 0, 0, 1, 1, 1, 0, 0, 0, 0),
(132037, '赐予生命的神灵只对仪祭师说话，$C。自然并未选择你作为它的勇士。', '赐予生命的神灵只对仪祭师说话，$C。自然并未选择你作为它的勇士。', 0, 0, 1, 0, 0, 0, 0, 0, 0),
(40042, '安瑟的光芒指引我们所有人。当黑暗降临时，正是借她的力量，我们将创造新的黎明。', '安瑟的光芒指引我们所有人。当黑暗降临时，正是借她的力量，我们将创造新的黎明。', 0, 0, 1, 1, 1, 0, 0, 0, 0),
(240042, '太阳魔法只服务于目的纯洁者，$C。你的动机并不明确。', '太阳魔法只服务于目的纯洁者，$C。你的动机并不明确。', 0, 0, 1, 0, 0, 0, 0, 0, 0);
