INSERT INTO `quest_offer_reward` (`ID`, `RewardText`)
VALUES
(55100, '永恒之焰在你身上认出了同类的灵魂，$N。$B$B火对牛头人来说是神圣的——从我们的仪式火焰到安瑟本身。作为炎术师，你将驾驭火焰的一切形态。你将召唤在水下燃烧的火焰，制造夷平堡垒的爆炸，从晴空中降下流星雨。$B$B你的火焰将燃烧着目的与判断力。你将理解火的双重本质——毁灭与创造、混乱与新生。掌握火球术，学会炎爆术，最终号令凤凰本身。$B$B欢迎来到炼狱之心。让你的火焰重塑世界！'),
(55101, '你听到了来自彼岸的低语，$N。并非所有牛头人都敢走上这条路。$B$B虚空提供先于大地母亲的力量，来自创世之前的只是。作为邪教徒，你将把疯狂转化为魔法，在混乱中看到真相，与不应存在的实体沟通。上古之神的影响从现实的裂隙中渗出。$B$B你将掌握虚空箭，学会散播疯狂，并打开通往超越理解的维度的裂隙。你的理智将持续受到考验，但作为回报，你获得超越凡人局限的力量。$B$B欢迎来到虚空的怀抱。让现实屈从于你的意志！'),
(55102, '群星选择了你，$N。穆莎和安瑟只是开始。$B$B作为唤星者，你从天体——恒星、卫星、彗星以及凡人视线之外的宇宙现象——中汲取力量。夜空成为你的魔典，星座成为你的法术。你将把星光引导为毁灭性的光束，召唤流星雨，并借助星风航行。$B$B牛头人一直仰望天空寻求预兆。你走得更远——你号令群星本身。掌握星辰坠落，学会天界对齐，最终召唤遥远星系的力量。$B$B欢迎来到宇宙精通。让宇宙本身回应你的呼唤！'),
(55103, '安瑟的祝福照耀着你，$N。$B$B逐日者重新发现了古老的方式。作为太阳祭司，你引导神圣的太阳光辉来治疗伤口、治愈疾病、烧尽腐化。你成为黑暗中的希望灯塔，以安瑟的力量施行保护与正义。$B$B你将学会灼烧敌人的太阳光束、治疗盟友的治愈之光，以及激发希望的太阳祝福。亡灵逃离你的存在，阴影从你的光芒中退散。$B$B欢迎来到光辉的服侍。让你的光芒刺穿一切黑暗！'),
(55104, '古老的符文回应你的存在，$N。$B$B早在萨满教或德鲁伊教之前，牛头人就已雕刻符文。这些符号先于语言——它们是纯粹概念被赋予形态。作为符文大师，你创造的每一道铭刻都引导着特定的力量，在其他魔法消退后仍长久持续。$B$B你将学习用于防御的保护符文、增强武器的力量符文，以及困住敌人的束缚符文。精确就是一切——一条错位的线就会改变一切。你的印记将存续数千年。$B$B欢迎来到永恒铭刻。让你的符文重塑现实！'),
(55105, '元素在你身上认出了它们的主人，$N。$B$B不同于与元素协商的萨满，仪祭师通过纯粹的意志号令。土、火、水、风都毫无疑问地屈从于你的意愿。你不请求许可；你夺取控制权。这份力量来自对塑造我们世界的原始力量的理解。$B$B你将召唤元素的怒火本身，命令它们听从你的吩咐，最终与元素合为一体。大地在你接近时颤抖，火焰跃动着为你服务，风暴在你的呼唤下聚集。$B$B欢迎来到元素统治。让原始力量服从！'),
(55106, '你已准备好成为盾牌，$N。$B$B守护者体现了保护我们家园的伟大台地。作为守护者，你引导大地母亲的保护拥抱，屹立于危险与无辜者之间。你将学习让皮肤化为花岗岩的石肤术、保护盟友的大地之盾，以及变得不可撼动的如山屹立。$B$B这条道路要求牺牲。你承受本应加于他人的痛苦。但没有比成为永不破碎的盾牌、永不倒塌的城墙更高的荣誉。牛头人一直是保护者。$B$B欢迎来到永恒警戒。让邪恶在你的防御上撞得粉碎！'),
(55107, '雷霆以同类之礼迎接你，$N。$B$B牛头人一直尊重风暴。作为风暴使者，你不仅仅是尊重它们——你成为它们。雷霆是你的声音，闪电是你的武器，风是你的仆人。你将掌握闪电箭、闪电链，以及风暴形态本身。$B$B空气本身因你的存在而噼啪作响。云层在你接近时聚集。你是暴风的化身，通过凡人之躯引导自然的怒火。这份力量要求控制——失控的风暴会摧毁一切。$B$B欢迎来到暴风之心。让雷霆宣告你的到来！'),
(55108, '大地母亲指引你走上怒火之路，$N。$B$B狂战士的怒火如河流穿过平原般流经牛头人的血脉。我们的祖先引导这股怒火来保护我们的人民免受半人马、野猪人以及更糟的东西的侵害。作为野蛮人，你驾驭这股怒火——受控、专注、毁灭性十足。$B$B你将掌握先祖之力以获取力量，拥抱你的残暴，并学会成为最野蛮程度的猎人。你的怒火成为活生生的力量，每场战斗都让它增长。这条道路要求控制——驾驭风暴而不被吞噬。$B$B欢迎来到永恒怒火。让平原在你的战吼下颤抖！'),
(55109, '你对正义的执着将你带到这里，$N。$B$B圣殿骑士结合了战士的力量与精神的力量。你成为正义的化身，每个行动都受大地母亲祝福，每次打击都承载神圣审判。你将掌握神圣打击、圣盾术以及奉献本身。$B$B牛头人一直为正义而战。作为圣殿骑士，你成为这些价值观的终极表达。你的存在削弱邪恶、增强善良，将任何战斗的天平倾向正义。$B$B欢迎来到神圣的服侍。让正义指引你的每一个行动！'),
(55110, '狩猎召唤你回家，$N。$B$B牛头人一直与自然和谐共处，但游侠走得更深。你与荒野合为一体，理解野兽的语言，追踪隐形的踪迹，在他人死亡的地方生存。你将驯服科多兽和陆行鸟，精通弓术，并阅读大地本身。$B$B我们的人民比以往任何时候都更需要游侠。贫瘠之地变得越来越危险，腐化蔓延，敌人蠢蠢欲动。你是我们在荒野中的眼睛，我们的第一道警告，我们的迅速回应。没有猎物能逃脱你的追捕。$B$B欢迎来到永恒的狩猎。让任何敌人都无法逃脱你的视线！'),
(200108, ''),
(200076, ''),
(200137, ''),
(200138, ''),
(200139, ''),
(200163, '啊哈！你已经向我证明了你真正强大。为此，我奖励你一个熊本身的象征。愿它在你的旅途中指引你，并赋予你战胜敌人的力量。'),
(200146, ''),
(200014, '这似乎就是那只猎鹰，看起来受伤了。'),
(200015, '猎鹰看起来很痛苦。一定是那个可疑的生物袭击了它！'),
(200016, '谢谢你找到基德。他已经回到我身边，和以前一样健康。$B$B我已经派他执行又一次侦察任务了。$B$B……你说在基德附近看到了一个奇怪的生物，它还攻击了你？那一定就是伤害我孩子的生物。$B$B我得进一步调查这件事。根据你的描述，不管这是什么，它都不是莫高雷的原生物。'),
(200032, '穆莎的恩典从你身上散发出来，$N。月亮很满意。$B$B我有两把受穆莎祝福的武器供你选择。$B$B作为穆莎的选民前进吧。我们会再见的。'),
(200101, ''),
(200102, ''),
(200103, ''),
(200064, '善行应有善报，$N。'),
(200082, '');
INSERT INTO `quest_request_items` (`ID`, `CompletionText`)
VALUES
(55100, '火焰在你眼中舞动，$N。你带来灼烧之书了吗？永恒之焰在召唤。'),
(55101, '虚空低语你的名字，$N。你带来虚空手稿了吗？远古力量在涌动。'),
(55102, '群星为你排列，$N。你带来天界星图了吗？宇宙之力在等待。'),
(55103, '安瑟的光芒照耀着你，$N。你带来太阳祈祷了吗？神圣光辉在等待。'),
(55104, '符文之力从你身上散发出来，$N。你带来牛头人符文石了吗？古老铭文在等待。'),
(55105, '元素在你周围汹涌，$N。你带来元素图腾了吗？原始力量在等待。'),
(55106, '大地母亲指引你的脚步，$N。你带来大地之盾石板了吗？守护者的职责在召唤。'),
(55107, '雷霆回响着你的脚步，$N。你带来雷霆呼唤了吗？风暴在聚集。'),
(55108, '先祖们谈论着你的到来，$N。你带来先祖战争石板了吗？怒火之路在等待。'),
(55109, '你的誓言有分量，$N。你带来神圣誓言了吗？正义在召唤。'),
(55110, '荒野在召唤你，$N。你带来平原猎手指南了吗？永恒的狩猎在等待。'),
(200108, ''),
(200076, ''),
(200137, ''),
(200138, ''),
(200139, ''),
(200163, '你已经将野猪人消灭了吗，$N？'),
(200146, ''),
(200014, ''),
(200015, ''),
(200016, '你没有辜负我，也没有辜负基德。谢谢你，$N。'),
(200032, ''),
(200101, ''),
(200102, ''),
(200103, ''),
(200064, '你找到吊坠了吗，$N？'),
(200082, '');
