INSERT INTO `page_text` (`ID`, `Text`, `NextPageID`)
VALUES
(10300, '内在之焰的守护者，$B$B你灵魂中搅动的火焰必须被照料，否则它会吞噬你。我将教你如何喂养它，并束缚它。$B$B在纳拉其营地的窑炉旁找我。$B$B学徒雅克·知识谷$B炎术师训练师', 0),
(10301, '聆听者，$B$B帷幕之外的低语已说出你的名字。我们族人中很少有人敢回应它们。你会的。$B$B在纳拉其营地西侧小屋的阴影中找我。$B$B乌尔莎·梦耙$B邪教徒训练师', 0),
(10302, '大地母亲之子，$B$B穆莎从夜空中注视着你。这张星图上的星辰等待着你去解读。$B$B在纳拉其营地中心的大图腾下找我。$B$B奥库恩，洛舒的选民$B唤星者训练师', 0),
(10303, '黎明的承载者，$B$B当你靠近时，安瑟的光芒燃烧得更加明亮。带着这份祈祷，学习将她的光辉既当作武器又当作盾牌来驾驭。$B$B在纳拉其营地东侧帐篷的火盆旁找我。$B$B逐日者·雷角$B太阳祭司训练师', 0),
(10304, '未来的守护者，$B$B这块石头上的刻痕比第一个萨满的歌谣还要古老。学会读懂它们，你将学会在世界本身上书写。$B$B在纳拉其营地东边缘的图腾间找我。$B$B戈罗$B符文大师训练师', 0),
(10305, '狂野者，$B$B大地在你的蹄下移动，火焰朝你倾斜。元素认识你；现在它们必须学会服从你。$B$B在纳拉其营地的酋长小屋中找我。$B$B阿穆瓦特·鹰梦$B仪祭师训练师', 0),
(10306, '部族的保护者，$B$B守护者屹立于危险与无法保护自己的人之间。像伟大的台地一样，你将变得不可撼动。$B$B在纳拉其营地的战士之环附近找我。$B$B莫塔·碎石$B守护者训练师', 0),
(10307, '风暴触碰者，$B$B天空在你上方聚集却收住了雨。那股怒火仍沉睡在你体内。我将教你唤醒它。$B$B在纳拉其营地的大鼓旁找我。$B$B图安图·云尾$B风暴使者训练师', 0),
(10308, '战士，$B$B先祖的怒火流淌在你的血液中。没有目标的怒火是浪费。我将教你瞄准它。$B$B在纳拉其营地东侧的兽皮架处找我。$B$B加拉克·双棍$B野蛮人训练师', 0),
(10309, '正义的勇士，$B$B你只取狩猎所需，不必要地伤害任何生灵。这种克制正是圣殿骑士之路的起点。$B$B在纳拉其营地东南图腾旁的路灯下找我。$B$B贾克斯·晨翔$B圣殿骑士训练师', 0),
(10310, '追踪者，$B$B你在他人只看到草地的地方读出了踪迹。荒野已标记了你；现在学习守护它们。$B$B在纳拉其营地西侧的射箭场找我。$B$B纳瓦特·风角$B游侠训练师', 0);
