INSERT INTO `creature` (`guid`, `id`, `map`, `zoneId`, `areaId`, `spawnMask`, `phaseMask`, `equipment_id`, `position_x`, `position_y`, `position_z`, `orientation`, `spawntimesecs`, `wander_distance`, `currentwaypoint`, `curhealth`, `curmana`, `MovementType`, `npcflag`, `unit_flags`, `dynamicflags`, `ScriptName`, `VerifiedBuild`, `CreateObject`, `Comment`)
VALUES
(9003900, 502950, 1, 0, 0, 1, 1, 1, -2883.4, -281.89, 53.917, 2, 300, 0, 0, 1, 0, 0, 0, 0, 0, '', NULL, 0, 'Camp Narache: Galak Twoclubs, Barbarian trainer: Camp Narache: SOURCED-CLIENT QuestSuperTrack turn-in point of quest 55108, z from surface.floor, at the kodo-hide rack on the east side; faces 2.000 toward the open ground west-south-west of the hide rack, the way players come from Grull Hawkwind and the camp centre'),
(9003901, 502774, 1, 0, 0, 1, 1, 1, -2899.55, -230, 53.894, 4.26, 300, 0, 0, 1, 0, 0, 0, 0, 0, '', NULL, 0, 'Camp Narache: Tooantuh Cloudtail, Stormbringer trainer: Camp Narache: SOURCED-CLIENT QuestSuperTrack turn-in point of quest 55107, z from surface.floor, between the tall totem and the great drum; faces 4.260 toward Grull Hawkwind and the start, where tauren come from with the Thunder Call'),
(9003902, 502790, 1, 0, 0, 1, 1, 1, -2887.29, -206.91, 54.821, 5.39, 300, 0, 0, 1, 0, 0, 0, 0, 0, '', NULL, 0, 'Camp Narache: Motah Stonebreaker, Guardian trainer: Camp Narache: SOURCED-CLIENT QuestSuperTrack turn-in point of quest 55106, z from surface.floor on the chief''s lodge floor (Taurenhutbig), "near the warrior''s circle" (page 10306); faces 5.390 into the open lodge toward the fire pit and the door (open-room direction)'),
(9003903, 9300300, 1, 0, 0, 1, 1, 1, -2921, -279, 53.917, 1.3, 300, 0, 0, 1, 0, 0, 0, 0, 0, '', NULL, 0, 'Camp Narache: Jax Dawnsoar, Templar trainer: Camp Narache: hand-placed (INFERRED) at the CoA-built station east-south-east of the start: the Taurentotem01 and its two lampposts exist only in CoA data (ct_diffprops), no other trainer claims them, and a lit ancestor totem suits a warrior-judge; Harutt Thunderhorn''s stock post stays his (section 0), inspected with inspect_area and passing surface.check; faces 1.300 toward Grull Hawkwind and the start, the way players arrive with the Sacred Oath'),
(9003904, 9300301, 1, 0, 0, 1, 1, 1, -2904.5, -203.5, 54.475, 5, 300, 0, 0, 1, 0, 0, 0, 0, 0, '', NULL, 0, 'Camp Narache: Nawat Windhorn, Ranger trainer: Camp Narache: hand-placed (INFERRED) at the archery range on the west side of the camp (Archerytargetdwarf01 at (-2912.6,-192.0)), on the flat end of the passage between the vendor hut and the lodge, inspected with inspect_area and passing surface.check; faces 5.000 down the passage toward the camp centre, the way players come up to the range'),
(9003905, 503403, 1, 0, 0, 1, 1, 1, -2903, -259.5, 52.942, 2.94, 300, 0, 0, 1, 0, 0, 0, 0, 0, '', NULL, 0, 'Camp Narache: Apprentice Yahk Loregrain, Pyromancer trainer: Camp Narache: hand-placed (INFERRED) beside the kiln north-north-east of the start (Taurenkiln01 at (-2905,-253)), 2.5 yd off its east face, the fire-keeper''s post for the apprentice pyromancer who "pats out a small fire on his beard" (200146), inspected with inspect_area and passing surface.check; faces 2.940 toward Grull Hawkwind and the start, with the kiln at his right shoulder'),
(9003906, 502834, 1, 0, 0, 1, 1, 1, -2938.22, -214.9, 53.917, 3.53, 300, 0, 0, 1, 0, 0, 0, 0, 0, '', NULL, 0, 'Camp Narache: Ultha Dreamharrow, Cultist trainer: Camp Narache: SOURCED-CLIENT QuestSuperTrack turn-in point of quest 55101, z from surface.floor, in the lee of the vendor hut; faces 3.530 out of the hut''s lee into the open ground players cross coming round the tall hut (the hut wall is 1.2 yd behind her)'),
(9003907, 50285, 1, 0, 0, 1, 1, 1, -2881.83, -242.2, 53.915, 3.4, 300, 0, 0, 1, 0, 0, 0, 0, 0, '', NULL, 0, 'Camp Narache: Oko''une, Chosen of Lo''sho, Starcaller trainer: Camp Narache: SOURCED-CLIENT QuestSuperTrack turn-in point of quest 55102, z from surface.floor, beneath the great totem (Taurentotem09) at the camp centre; faces 3.400 away from the great totem toward the kiln and the start (3.56), the way letter-bearers come'),
(9003908, 100242, 1, 0, 0, 1, 1, 1, -2873.64, -268.52, 53.917, 2.69, 300, 0, 0, 1, 0, 0, 0, 0, 0, '', NULL, 0, 'Camp Narache: Sunwalker Thunderhorn, Sun Cleric trainer: Camp Narache: SOURCED-CLIENT QuestSuperTrack turn-in point of quest 55103, z from surface.floor by the east tepee and the brazier; faces 2.690, the stock facing at this post (Gart Mistrunner''s, 0.17 yd away), toward Grull Hawkwind and the start'),
(9003909, 502900, 1, 0, 0, 1, 1, 1, -2862.48, -230.31, 54.821, 2.57, 300, 0, 0, 1, 0, 0, 0, 0, 0, '', NULL, 0, 'Camp Narache: Amuwate Eagledream, Primalist trainer: Camp Narache: SOURCED-CLIENT QuestSuperTrack turn-in point of quest 55105, z from surface.floor on the lodge floor by the giant drum; faces 2.570 across the lodge between the fire pit and the door (open-room direction)'),
(9003910, 512912, 1, 0, 0, 1, 1, 1, -2905.52, -287.11, 53.901, 1.97, 300, 0, 0, 1, 0, 0, 0, 0, 0, '', NULL, 0, 'Camp Narache: Go''hro, Runemaster trainer: Camp Narache: SOURCED-CLIENT QuestSuperTrack turn-in point of quest 55104, z from surface.floor at the east edge by Taurentotem05; faces 1.970 toward the start and Grull Hawkwind, the open side of his post'),
(9003911, 299238, 1, 0, 0, 1, 1, 1, -2870.5, -213.5, 54.821, 4, 60, 0, 0, 1, 0, 0, 0, 0, 0, '', NULL, 0, 'Camp Narache: inside the chief''s lodge (Taurenhutbig floor 54.82), the north-west side of the fire pit, 11 yd from Chief Hawkwind and 11 yd from Harutt Thunderhorn; faces the lodge door; unique target, 60 s respawn'),
(9003912, 299329, 1, 0, 0, 1, 1, 1, -2880.5, -289.5, 53.919, 0.3, 60, 0, 0, 1, 0, 0, 0, 0, 0, '', NULL, 0, 'Camp Narache: skulking behind Galak Twoclubs'' kodo-hide rack, 7.7 yd from him (in the Valley of Trials the warband rookie''s SuperTrack objective point is the Barbarian trainer''s own post, 200107); faces north toward the tepee side players come from; unique target, 60 s respawn'),
(9003913, 9300302, 1, 0, 0, 1, 1, 0, -3045.5, -455, 40.493, 1, 60, 0, 0, 1, 0, 0, 0, 0, 0, '', NULL, 0, 'Camp Narache: grove of Mulgore trees 250 yd south-east of the camp, at the foot of the big tree, where the falcon came down while scouting; faces north-west toward Camp Narache'),
(9003914, 9300303, 1, 0, 0, 1, 1, 0, -3119.5, -868, 53.736, 1.25, 60, 0, 0, 1, 0, 0, 0, 0, 0, '', NULL, 0, 'Camp Narache: east side of the mesa below the ridge and the copse (the far side from the camp), beside his campfire; faces west toward the mesa, the way players come; unique, 60 s respawn'),
(9003915, 685033, 1, 0, 0, 1, 1, 0, -3450, -153.5, 116.194, 0.63, 300, 0, 0, 1, 0, 0, 0, 0, 0, '', NULL, 0, 'Camp Narache: on the ridge ledge above Seer Graytongue''s fire, at the shrine to Mu''sha; walk-in credit within 10 yd'),
(9003916, 685037, 1, 0, 0, 1, 1, 0, -3423.5, -219, 61.875, 3.14, 300, 0, 0, 1, 0, 0, 0, 0, 0, '', NULL, 0, 'Camp Narache: in front of the hidden statue at the head of the south valley; walk-in credit within 8 yd');
INSERT INTO `gameobject` (`guid`, `id`, `map`, `zoneId`, `areaId`, `spawnMask`, `phaseMask`, `position_x`, `position_y`, `position_z`, `orientation`, `rotation0`, `rotation1`, `rotation2`, `rotation3`, `spawntimesecs`, `animprogress`, `state`, `ScriptName`, `Comment`)
VALUES
(7912500, 1798, 1, 0, 0, 1, 1, -3121.5, -865, 53.107, 0, 0, 0, 0, 1, 300, 100, 1, '', 'Camp Narache: Scorch''s campfire on the flattest ground (9 deg) below the east ridge'),
(7912501, 9301301, 1, 0, 0, 1, 1, -3426, -219, 62.316, 0, 0, 0, 0, 1, 300, 100, 1, '', 'Camp Narache: head of the secluded south valley at the foot of the southern mountains (southern Red Cloud Mesa), facing north down the valley toward the way in'),
